mapper.insert:
CREATE TABLE IF NOT EXISTS ${format}_key_value (
  key_value_id    INT GENERATED BY DEFAULT AS IDENTITY,
  repository_id   INT NOT NULL,
  category        VARCHAR NOT NULL,
  key             VARCHAR NOT NULL,
  value           VARCHAR,
  created         TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

  CONSTRAINT pk_${format}_key_value_id PRIMARY KEY (key_value_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_${format}_repository_category_key
    ON ${format}_key_value (repository_id, category, key);

CREATE INDEX IF NOT EXISTS idx_${format}_key_value_repository_key
    ON ${format}_key_value(repository_id, key);

-- Additional index for improved concurrent access performance with Virtual Threads
CREATE INDEX IF NOT EXISTS idx_${format}_key_value_category
    ON ${format}_key_value(category);

CREATE TABLE IF NOT EXISTS ${format}_key_value (
   key_value_id    INT GENERATED BY DEFAULT AS IDENTITY,
   repository_id   INT NOT NULL,
   category        VARCHAR NOT NULL,
   `key`             VARCHAR NOT NULL,
   `value`           CHARACTER LARGE OBJECT,
   created         TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

   CONSTRAINT pk_${format}_key_value_id PRIMARY KEY (key_value_id)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_${format}_repository_category_key
  ON ${format}_key_value (repository_id, category, `key`);

CREATE INDEX IF NOT EXISTS idx_${format}_key_value_repository_key
  ON ${format}_key_value(repository_id, `key`);

-- Additional index for improved concurrent access performance with Virtual Threads
CREATE INDEX IF NOT EXISTS idx_${format}_key_value_category
  ON ${format}_key_value(category);

mapper.select:
/*+ MAX_EXECUTION_TIME(30000) */
SELECT key_value_id, category, key, value
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
   AND category = #{category}
    AND key > #{continuationToken}
 ORDER BY key
 LIMIT #{limit};

SELECT key_value_id, category, `key`, `value`
FROM ${format}_key_value
WHERE repository_id = #{repositoryId}
AND category = #{category}
 AND `key` > #{continuationToken}
ORDER BY `key`
LIMIT #{limit};

SELECT DISTINCT category
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId};

SELECT count(*)
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
  AND category = #{category};

/*+ MAX_EXECUTION_TIME(15000) */
SELECT category
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
   AND key = #{key};

SELECT category
FROM ${format}_key_value
WHERE repository_id = #{repositoryId}
  AND `key` = #{key};

/*+ MAX_EXECUTION_TIME(10000) */
SELECT value
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
   AND category = #{category}
   AND key = #{key};

SELECT `value`
FROM ${format}_key_value
WHERE repository_id = #{repositoryId}
  AND category = #{category}
  AND `key` = #{key};

/*+ MAX_EXECUTION_TIME(30000) */
SELECT key_value_id, category, key, value
  FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
    AND category = #{category}
   AND key LIKE #{keyLike};

SELECT key_value_id, category, `key`, `value`
FROM ${format}_key_value
WHERE repository_id = #{repositoryId}
 AND category = #{category}
AND `key` LIKE #{keyLike};

mapper.update:
/*+ MAX_EXECUTION_TIME(20000) */
WITH upsert AS (
  UPDATE ${format}_key_value
     SET value = #{value},
         created = now()
   WHERE repository_id = #{repositoryId}
     AND category = #{category}
     AND key = #{key}
  RETURNING *
)
INSERT INTO ${format}_key_value (repository_id, category, key, value, created)
SELECT #{repositoryId}, #{category}, #{key}, #{value}, now()
WHERE NOT EXISTS (SELECT 1 FROM upsert);

mapper.delete:
/*+ MAX_EXECUTION_TIME(15000) */
DELETE FROM ${format}_key_value
      WHERE repository_id = #{repositoryId}
        AND category = #{category}
        AND key = #{key};

DELETE FROM ${format}_key_value
WHERE repository_id = #{repositoryId}
  AND category = #{category}
  AND `key` = #{key};

DELETE FROM ${format}_key_value
 WHERE repository_id = #{repositoryId}
   AND category = #{category}
   LIMIT #{limit};

/*+ MAX_EXECUTION_TIME(45000) */
DELETE FROM ${format}_key_value
 WHERE key_value_id IN (SELECT key_value_id
                          FROM ${format}_key_value
                         WHERE repository_id = #{repositoryId}
                             AND category = #{category}
   LIMIT #{limit});

/*+ MAX_EXECUTION_TIME(60000) */
DELETE FROM ${format}_key_value
 WHERE key_value_id IN (SELECT key_value_id
                         FROM ${format}_key_value
                        WHERE repository_id = #{repositoryId}
  LIMIT #{limit});

mapper.update:
/*+ MAX_EXECUTION_TIME(45000) */ WITH batch_data(repo_id, cat, k, v) AS ( VALUES
(#{item.repositoryId}, #{item.category}, #{item.key}, #{item.value})
), upserts AS ( UPDATE ${format}_key_value kv SET value = bd.v, created = now() FROM batch_data bd WHERE kv.repository_id = bd.repo_id AND kv.category = bd.cat AND kv.key = bd.k RETURNING kv.repository_id, kv.category, kv.key ) INSERT INTO ${format}_key_value (repository_id, category, key, value, created) SELECT bd.repo_id, bd.cat, bd.k, bd.v, now() FROM batch_data bd WHERE NOT EXISTS ( SELECT 1 FROM upserts u WHERE u.repository_id = bd.repo_id AND u.category = bd.cat AND u.key = bd.k );
